var language = Context.getSelectedLanguage();
var models = ArisData.getSelectedModels();
var workbook = Context.createExcelWorkbook(Context.getSelectedFile());
var sheet = workbook.createSheet("Models");
sheet.createRow(0).createCell(0).setCellValue("Model name");

for (var i = 0; i < models.length; i++) {
    var row = sheet.createRow(i + 1);
    row.createCell(0).setCellValue(models[i].Name(language));
}

workbook.write();

var language = Context.getSelectedLanguage();
var models = ArisData.getSelectedModels();
var workbook = Context.createExcelWorkbook(Context.getSelectedFile());
var sheet = workbook.createSheet("Function counts");
var header = sheet.createRow(0);
header.createCell(0).setCellValue("Model name");
header.createCell(1).setCellValue("Function occurrences");

for (var i = 0; i < models.length; i++) {
    var count = models[i].ObjOccListFilter(Constants.OT_FUNC).length;
    var row = sheet.createRow(i + 1);
    row.createCell(0).setCellValue(models[i].Name(language));
    row.createCell(1).setCellValue(count);
}

workbook.write();
